        /// <summary>
        /// Active method to set form controls and fields
        /// </summary>
        /// <returns> int value of the form object </returns>
        public int active()
        {
            int ret;
        
            ret = super();

            METCBCTInvoicePosting.enabled(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
            InvoiceHeaderTable_ds.allowEdit(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
            InvoiceHeaderTable_ds.allowDelete(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
            InvoiceLine_ds.allowEdit(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
            InvoiceLine_ds.allowCreate(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
            InvoiceLine_ds.allowDelete(InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created);
        
            return ret;
        }

/// <summary>
///Display method for customer name 
/// </summary>
/// <param name="_invoiceHeaderTable">
/// The instance of <c>METCBCTInvoiceHeaderTable</c> table.
/// </param>
/// <returns> Customer name of the customer account linked to invoice header</returns>
[SysClientCacheDataMethodAttribute(true)]
public display CustName getCustName(METCBCTInvoiceHeaderTable _invoiceHeaderTable)
{
    CustName    custName;
    if (_invoiceHeaderTable.CustomerAccount)
    {
        custName = CustTable::find(_invoiceHeaderTable.CustomerAccount).name();
        return custName;
    }
    else
    {
        return '';
    }
}

/// <summary>
/// Get vendor name
/// </summary>
/// <param name="_invoiceHeaderTable">
/// The instance of <c>METCBCTInvoiceHeaderTable</c> table.
/// </param>
/// <returns> Vendor name of the vendor account linked to invoice header</returns>
[SysClientCacheDataMethodAttribute(true)]
public display VendName getVendName(METCBCTInvoiceHeaderTable _invoiceHeaderTable)
{
    VendName    vendName;
    if (_invoiceHeaderTable.VendorAccount)
    {
        vendName = VendTable::find(_invoiceHeaderTable.VendorAccount).name();
        return vendName;
    }
    else
    {
        return '';
    }
}

        /// <summary>
        /// Init value 
        /// </summary>
        public void initValue()
        {
            METVendTable    metVendTable;
            CustTable       custTable = CustTable::find(InvoiceHeaderTable.CustomerAccount);

            select firstonly metVendTable where metVendTable.AccountNum == InvoiceHeaderTable.VendorAccount;
            super();
            
            //Default item from the service item defined on the vendor
            InvoiceLine.ItemId = metVendTable.CBCTServiceItemId;
            InvoiceLine.TaxItemGroup = InventTableModule::find(metVendTable.CBCTServiceItemId,ModuleInventPurchSales::Purch).TaxItemGroupId;
            InvoiceLine.TaxGroup = custTable.TaxGroup; //Default from customer as default line type is customer
            InvoiceLine.InventSiteId = custTable.InventSiteId;
            InvoiceLine.InventLocationId = custTable.InventLocation;
            InvoiceLine.FinancialDimension = METCBCTInvoiceLine::initFinancialDimension(metVendTable.CBCTServiceItemId,InvoiceHeaderTable.FinancialDimension);
        }

            /// <summary>
            /// Modified line type 
            /// </summary>
            public void modified()
            {
                super();
                switch(InvoiceLine.VendCustType)
                {
                    case METCBCTVendCust::Vend:
                        InvoiceLine.TaxGroup = VendTable::find(InvoiceHeaderTable.VendorAccount).TaxGroup;
                        break;

                    case METCBCTVendCust::Cust:
                        InvoiceLine.TaxGroup = CustTable::find(InvoiceHeaderTable.CustomerAccount).TaxGroup;
                        break;
                }
            }

