/// <summary>
/// Create new invoice line of type customer
/// </summary>
public void clicked()
{
    //super();
    InvoiceLine_ds.create();
    InvoiceLine.VendCustType = METCBCTVendCust::Cust;
}

        void clicked()
        {
            Args args = new Args();
            MenuFunction menuFunction;

            args.caller(element);
            args.record(InvoiceLine);

            menuFunction = new MenuFunction(menuitemDisplayStr(MarkupTrans_LinePurchParm), MenuItemType::Display);
            menuFunction.run(args);
        }
